function sort(uint256[] memory a) internal pure {

        assembly {
            let w := not(31)
            let s := 0x20
            let n := mload(a) 
            mstore(a, 0) 


            let stack := mload(0x40)

            for {} iszero(lt(n, 2)) {} {


                let l := add(a, s)
                let h := add(a, shl(5, n))

                let j := l

                for {} iszero(or(eq(j, h), gt(mload(j), mload(add(j, s))))) {} {
                    j := add(j, s)
                }

                if eq(j, h) { break }

                j := h

                for {} iszero(gt(mload(j), mload(add(j, w)))) {} {
                    j := add(j, w) 
                }

                if eq(j, l) {
                    for {} 1 {} {
                        let t := mload(l)
                        mstore(l, mload(h))
                        mstore(h, t)
                        h := add(h, w) 
                        l := add(l, s)
                        if iszero(lt(l, h)) { break }
                    }
                    break
                }


                mstore(stack, l)
                mstore(add(stack, s), h)
                stack := add(stack, 0x40)
                break
            }

            for { let stackBottom := mload(0x40) } iszero(eq(stack, stackBottom)) {} {

                stack := sub(stack, 0x40)
                let l := mload(stack)
                let h := mload(add(stack, s))



                if iszero(gt(sub(h, l), 0x180)) {

                    let i := add(l, s)
                    if iszero(lt(mload(l), mload(i))) {
                        let t := mload(i)
                        mstore(i, mload(l))
                        mstore(l, t)
                    }
                    for {} 1 {} {
                        i := add(i, s)
                        if gt(i, h) { break }
                        let k := mload(i) 
                        let j := add(i, w) 
                        let v := mload(j) 
                        if iszero(gt(v, k)) { continue }
                        for {} 1 {} {
                            mstore(add(j, s), v)
                            j := add(j, w)
                            v := mload(j)
                            if iszero(gt(v, k)) { break }
                        }
                        mstore(add(j, s), k)
                    }
                    continue
                }

                let p := add(shl(5, shr(6, add(l, h))), and(31, l))

                {
                    let e0 := mload(l)
                    let e2 := mload(h)
                    let e1 := mload(p)
                    if iszero(lt(e0, e1)) {
                        let t := e0
                        e0 := e1
                        e1 := t
                    }
                    if iszero(lt(e0, e2)) {
                        let t := e0
                        e0 := e2
                        e2 := t
                    }
                    if iszero(lt(e1, e2)) {
                        let t := e1
                        e1 := e2
                        e2 := t
                    }
                    mstore(p, e1)
                    mstore(h, e2)
                    mstore(l, e0)
                }

                {

                    let x := mload(p)
                    p := h
                    for { let i := l } 1 {} {
                        for {} 1 {} {
                            i := add(i, s)
                            if iszero(gt(x, mload(i))) { break }
                        }
                        let j := p
                        for {} 1 {} {
                            j := add(j, w)
                            if iszero(lt(x, mload(j))) { break }
                        }
                        p := j
                        if iszero(lt(i, p)) { break }

                        let t := mload(i)
                        mstore(i, mload(p))
                        mstore(p, t)
                    }
                }

                {
                    mstore(stack, add(p, s))

                    stack := add(stack, shl(6, lt(add(p, s), h)))
                }

                {
                    mstore(stack, l)
                    mstore(add(stack, s), p)
                    stack := add(stack, shl(6, gt(p, l)))
                }
            }
            mstore(a, n) 
        }
    }

